import {recipes,layer} from './ingredients.js';
// Single source of truth (choosing another product starts its Personalização over; the cart stays): { product: Receita id, editing, removed: applied ids, draft: ids in the open editor, combo, cart }.
export const initial={product:'whopper',removed:[],draft:[],editing:false,combo:false,cart:[]};
export function reducer(s,a){switch(a.type){case'select':return s.product===a.product||!recipes[a.product]?s:{...s,product:a.product,removed:[],draft:[],editing:false};case'open':return {...s,editing:true,draft:[...s.removed]};case'toggle':if(!s.editing||layer(recipes[s.product],a.id)?.locked)return s;return {...s,draft:s.draft.includes(a.id)?s.draft.filter(x=>x!==a.id):[...s.draft,a.id]};case'remove':return s.draft.includes(a.id)?s:reducer(s,{type:'toggle',id:a.id});case'reset':return {...s,draft:[]};case'apply':return {...s,editing:false,removed:[...s.draft]};case'cancel':return {...s,editing:false,draft:[]};case'combo':return {...s,combo:a.value};case'add':return {...s,cart:[...s.cart,{product:s.product,removed:[...s.removed],combo:s.combo,price:price(s)}]};case'delete':return {...s,cart:s.cart.filter((_,i)=>i!==a.index)};default:return s}}
export const comboFee=1200,money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),price=s=>recipes[s.product].price+(s.combo?comboFee:0);
